                        return *this;
                }

                Prototype &Prototype::assign_object(::FLAC__StreamMetadata *object, bool copy)
                {
                        FLAC__ASSERT(0 != object);
                        clear();
                        object_ = (copy? ::FLAC__metadata_object_clone(object) : object);
                        is_reference_ = false;
                        return *this;
                }

